def test_modelmultiplechoicefield_invalid_list(self):
    for error_messages, message in (
        ({}, 'Enter a list of values.'),
        ({'invalid_list': 'NOT A LIST OF VALUES'}, 'NOT A LIST OF VALUES'),
    ):
        field = ModelMultipleChoiceField(
            queryset=ChoiceModel.objects.all(), error_messages=error_messages,
        )
        for value in ('3', 3, [['3']], [{'pk': 3}]):
            with self.subTest(value=value, error_messages=error_messages):
                with self.assertRaises(ValidationError) as cm:
                    field.clean(value)
                self.assertEqual(cm.exception.code, 'invalid_list')
                self.assertEqual(cm.exception.messages, [message])
